scripts.酒客组1对话.txt:
// 与酒客1的对话

	If($Map050jiuke1 == 0) @Talk0;
	If($Map050jiuke1 == 1) @Talk1;
	If($Map050jiuke1 == 2) @Talk2;
	If($Map050jiuke1 == 3) @Talk3;
	If($Map050jiuke1 == 4) @Talk4;
	
@Talk0:
	Say("胡子：老弟，你可听说过《壶中谱》？");
	Say("胖子：可是五十年前洞庭湖上“湖岛醉仙”钟午子的不传医诀？");
	Say("胡子：正是，如果能得到这份医诀，李将军的绝症或许有救。");
	Assign($Map050jiuke1,1);
	Return;
	
@Talk1:
	Say("胡子：传说钟午子平生有两大绝学——“倒虚天”神功和《壶中谱》……");
	Say("胖子：可惜学会这绝世医学的就只有他的三弟子道一。");
	Say("胡子：这些徒弟只知杀人之法，却不学救人之术……焉不知杀千人易，救一人难啊！");
	Assign($Map050jiuke1,2);
	Return;
	
@Talk2:
	Say("胖子：这道一一死，世上恐怕再无人能将这神奇医术传扬下去……");
	Say("胡子：他的两个弟子，“药仙”古柏和“丹王”妙松不都是当世神医吗？");
	Say("胖子：只可惜，他俩各偏一道，未能融而通贯……");
	Assign($Map050jiuke1,3);
	Return;
	
@Talk3:
	Say("胡子：李将军这次怕是大限已到，我看撑不过今年了。");
	Say("胖子：诸王子各藏私心，西夏国恐怕又有一场大变……");
	Assign($Map050jiuke1,4);
	Return;
	
@Talk4:
	Say("胖子：客官欲知后事，且听“剑三”分解。");
	Return;

scripts.酒客组2对话.txt:
// 与酒客2的对话

	If($Map050jiuke2 == 0) @Talk0;
	If($Map050jiuke2 == 1) @Talk1;
	
@Talk0:
	Say("肇浩：咱哥俩有多长时间没有这样坐在一起喝酒了？");
	Say("肇雍：算算也有一年了吧？唉！时局不好，兵荒马乱的，那还有心情喝酒！");
	Say("肇浩：今儿咱们难得聚在一起，要喝个一醉方休，不醉不归！");
	Say("肇雍：对！来，大哥，我敬你一杯！"); 
	Assign($Map050jiuke1,1);
	Return;
	
@Talk1:
	Say("肇浩：这些年来我在外面闯荡，最挂念的人就是你，总是担心你不会照顾自己……");
	Say("肇雍：大哥，你放心好了，我已经长大成人，俗语说的好，男儿志在四方，总有一天我要和你一样到外面去闯荡世界！");
	Say("肇浩：好！有志气，到时咱哥俩一起到江湖上闯出个名堂！");
	Say("肇雍：大哥，我再敬你一杯！"); 
	Return;

scripts.酒店老板对话.txt:
// 与酒店老板对话

	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
	If ($Value == 1) @YuanDan;	
	
@NotYuanDan:

	If ($Event == 301) @Event301;
	If ($Event == 304) @Event304;
	If ($Event == 305) @Event304;	
	
	GetRandNum($Talklaoban, 0, 2);
	If($Talklaoban == 0) @Talklaoban0;
	If($Talklaoban == 1) @Talklaoban1;
	If($Talklaoban == 2) @Talklaoban2;
	
 @Talklaoban0:
	Say("酒店掌柜：时逢乱世，生意也不好做啊，每天都这么冷冷清清，没几个人上门。", 85);
	Return;
 @Talklaoban1:
	Say("酒店掌柜：客官若想清静就请上二楼。", 85);
	Return;
 @Talklaoban2:
	Say("酒店掌柜：公子相貌堂堂，气度不凡，真是稀客啊！", 85);	
	Return;


@Event301:
	Say("酒店掌柜：最近有个年轻人经常来喝得酩酊大醉，好象有什么心事想不开哪。", 85);
	Return;

@Event304:
	Say("酒店掌柜：公子还要喝酒吗？这里有新到的苏州林记的陈年女儿红。", 85);
	Say("张如梦：下……下次吧。", 20);
	Return;
	
	
	
