	Return;
 @Talklaoban1YD:
	Say("酒店掌柜：恭贺新禧！客官若想清静就请上二楼。", 85);
	Return;
 @Talklaoban2YD:
	Say("酒店掌柜：恭贺新禧！公子相貌堂堂，气度不凡，真是稀客啊！", 85);	
	Return;


@Event301YD:
	Say("酒店掌柜：最近有个年轻人经常来喝得酩酊大醉，好象有什么心事想不开哪。", 85);
	Return;

@Event304YD:
	Say("酒店掌柜：公子还要喝酒吗？这里有新到的苏州林记的陈年女儿红。", 85);
	Say("张如梦：下……下次吧。", 20);
	Return;

